    "ody: JSON.stringify({level: val})}).catch(() => {});}}function toggleAutoScroll() {logAutoScroll = !"
    "logAutoScroll;const btn = document.getElementById('autoScrollBtn');btn.innerText = logAutoScroll ? '"
    "⏬ 滚屏: 开' : '⏸️ 滚屏: 关';btn.style.borderColor = logAutoScroll ? 'var(--accent)' : 'var(--border)';}fun"
    "ction toggleLogPause() {logIsPaused = !logIsPaused;const btn = document.getElementById('pauseLogBtn'"
    ");const badge = document.getElementById('logStreamBadge');if (logIsPaused) {btn.innerText = '▶️ 继续';"
    "badge.innerText = '⏸️ 已暂停';badge.style.color = 'var(--muted)';} else {btn.innerText = '⏸️ 暂停';badge."
    "innerText = '● 实时监听中';badge.style.color = 'var(--accent-sub)';}}function clearLocalLogs() {logLinesD"
    "ata = [];document.getElementById('terminalWindow').innerHTML = '<div class=\"log-line\" style=\"colo"
    "r:var(--muted)\">[UI] 视图已清空</div>';}function clearDeviceLogs() {if (!confirm('确认清空端侧循环日志缓冲区？')) retu"
    "rn;fetch('/api/logs/clear', {method: 'POST'}).then(r => r.json()).then(() => {clearLocalLogs();logCu"
    "rsor = 0;document.getElementById('logCursorTag').innerText = 'Cursor: 0 B';}).catch(() => alert('清空失"
    "败'));}function exportLogs() {const text = logLinesData.map(e => e.raw).join('\\n');const blob = new "
    "Blob([text], {type: 'text/plain;charset=utf-8'});const url = URL.createObjectURL(blob);const a = doc"
    "ument.createElement('a');a.href = url;a.download = 'phoenix_logs_' + new Date().toISOString().replac"
    "e(/[:.]/g, '-') + '.log';a.click();URL.revokeObjectURL(url);}/* ===================================="
    "====================* 工具与辅助函数* ======================================================== */function f"
    "ormatBytes(b) {if (!b || b === 0) return '0 B';const k = 1024;const sizes = ['B', 'KB', 'MB', 'GB'];"
    "const i = Math.floor(Math.log(b) / Math.log(k));return (b / Math.pow(k, i)).toFixed(1) + ' ' + sizes"
    "[i];}function escapeHtml(s) {if (!s) return '';return String(s).replace(/&/g, '&amp;').replace(/</g,"
    " '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');}function syncClientTimeToDevice() {const ts"
    " = Math.floor(Date.now() / 1000);fetch('/api/system/time', {method: 'POST',headers: {'Content-Type':"
    " 'application/json'},body: JSON.stringify({timestamp: ts})}).catch(() => {});}// 页面可见性挂起策略：离开浏览器前台时降"
    "频轮询document.addEventListener('visibilitychange', () => {if (document.hidden) {if (statusPollTimer) c"
    "learInterval(statusPollTimer);statusPollTimer = setInterval(refreshStatus, 5000);} else {if (statusP"
    "ollTimer) clearInterval(statusPollTimer);statusPollTimer = setInterval(refreshStatus, 2000);refreshS"
    "tatus();}});// 初始启动refreshStatus();statusPollTimer = setInterval(refreshStatus, 2000);loadAgentConfi"
    "g();refreshAgentTools();syncClientTimeToDevice();</script></body></html>";

